{
  "title": "HCV Adherence World",
  "perWatchSecond": 2,
  "levels": [
    {
      "kind": "hook",
      "title": "The Adherence Threshold",
      "goal": "See how treatment adherence stops the epidemic.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence",
        "lowEnd": "0.0",
        "highEnd": "1.0"
      },
      "watch": "s",
      "whatIf": {
        "prompt": "Adherence is raised above the 52% threshold.",
        "parameter": "theta",
        "value": 0.6
      },
      "difference": {
        "compartment": "s",
        "summary": "at",
        "at": 100,
        "time": 100,
        "relation": "higher",
        "by": 0.05
      },
      "effect": "The world with higher adherence has susceptible people higher by more than 0.05 at year 100.",
      "prediction": {
        "prompt": "Adherence is raised above the 52% threshold.",
        "claimed": "Susceptible people stay higher.",
        "other": "Susceptible people drop same."
      },
      "passage": {
        "title": "Adherence Threshold",
        "quote": "The study demonstrated that an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "You saw adherence controls the epidemic."
    },
    {
      "kind": "background",
      "title": "Quitting Treatment",
      "goal": "See how quitting treatment affects the quit compartment.",
      "control": {
        "parameter": "delta",
        "label": "Treatment quitting rate",
        "lowEnd": "0.0",
        "highEnd": "1.0"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "Quitting rate is cut in half.",
        "parameter": "delta",
        "value": 0.3
      },
      "difference": {
        "compartment": "cq",
        "summary": "at",
        "at": 40,
        "time": 80,
        "relation": "lower",
        "by": 0.005
      },
      "effect": "The world with half the quitting rate has quit treatment people lower by more than 0.005 at year 40.",
      "prediction": {
        "prompt": "Quitting rate is cut in half.",
        "claimed": "Quit treatment people peak lower.",
        "other": "Quit treatment people peak same."
      },
      "passage": {
        "title": "Quitting Transmissibility",
        "quote": "We assumed that $β_{2} < β_{3}$, since quitting treatment before reaching sustained viral response (SVR) increases HCV viral load, leading to higher transmissibility [[citation]–[citation]]."
      },
      "carryForward": "You saw quitting fills the infectious pool."
    },
    {
      "kind": "result",
      "title": "Quitter Transmission",
      "goal": "See how quitters infect others.",
      "control": {
        "parameter": "beta3",
        "label": "Quitter transmission rate",
        "lowEnd": "0.01",
        "highEnd": "0.1"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "Quitters become less infectious.",
        "parameter": "beta3",
        "value": 0.016
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 100,
        "time": 100,
        "relation": "lower",
        "by": 0.001
      },
      "effect": "The world with reduced transmission from quitters has acutely infected people lower by more than 0.001 at year 100.",
      "prediction": {
        "prompt": "Quitters become less infectious.",
        "claimed": "Acutely infected people decline faster.",
        "other": "Acutely infected people decline same."
      },
      "passage": {
        "title": "Study Aim",
        "quote": "Our study employed a mathematical model to explain the impact of poor treatment adherence on HCV transmission dynamics in Zimbabwe."
      },
      "carryForward": "You saw quitters drive new infections."
    }
  ],
  "limits": [
    "Time unit is year.",
    "Parameters ending in 0 are starting values.",
    "Watch the graph line for the chosen compartment."
  ]
}
